 function products(){const snapshot=current?.snapshot||state?.snapshot;if(!snapshot)return;const cat=$('categories');cat.replaceChildren();const all=el('button','جميع الأصناف',category===''?'active':'');all.onclick=()=>{category='';products();};cat.append(all);for(const c of snapshot.categories){const b=el('button',c.name,String(c.id)===category?'active':'');b.onclick=()=>{category=String(c.id);products();};cat.append(b);}const box=$('products');box.replaceChildren();for(const p of snapshot.products){if(category&&String(p.category_id)!==category)continue;if(!$('search').value||p.name.includes($('search').value)){const card=el('div',undefined,'product');card.append(el('strong',p.name));const choice=el('select');for(const v of p.variants){const priced=Number.isSafeInteger(v.unit_price_cents)&&v.unit_price_cents>0;const opt=el('option',v.label+' — '+(priced?D.money(v.unit_price_cents)+' ج':'السعر غير محدد'));opt.value=v.option_id;opt.disabled=!priced;choice.append(opt);}card.append(choice);const unit=el('select');for(const [value,label] of [['piece','بالقطعة'],['weight','بالكيلو']]){const opt=el('option',label);opt.value=value;unit.append(opt);}unit.value=p.unit==='kg'?'weight':'piece';unit.hidden=!p.variants.some(v=>v.quantity_mode==='select');card.append(unit);const add=el('button','+ إضافة');add.disabled=!current||current.status==='bill'||!p.variants.some(v=>Number.isSafeInteger(v.unit_price_cents)&&v.unit_price_cents>0);add.onclick=()=>run(async()=>{await persist();const d=collect(),v=p.variants.find(v=>v.option_id===choice.value),mode=v.quantity_mode==='select'?unit.value:v.quantity_mode;const existing=d.items.find(i=>i.product_id===p.id&&i.option_id===choice.value&&i.quantity_mode===mode);if(existing)existing.quantity=(D.decimal(existing.quantity,3)/1000+(mode==='weight'?.25:1)).toFixed(3);else d.items.push({product_id:p.id,option_id:choice.value,quantity_mode:mode,quantity:mode==='weight'?'0.250':'1'});current=await POS.update(current.id,d);render();});card.append(add);box.append(card);}}}
 async function action(kind){await persist();message('');const event=await POS.action(current.id,kind,kind==='cancel'?'إلغاء قبل الإرسال':'');current=await POS.order(current.id);if(['kitchen','bill','sale'].includes(kind)){try{await POS.print(event.id);}catch(e){message(e.message+' — يمكنك إعادة الطباعة من سجل العمليات.');}}if(['sale','cancel','kitchen'].includes(kind)){const s=await POS.state();applyState(s);const draft=s.orders.find(o=>o.status==='draft');if(draft)await select(draft.id);else{current=await POS.new();fields();render();applyState(await POS.state());}}else{render();applyState(await POS.state());}POS.sync().catch(e=>message(e.message));}
 function history(){const saved=$('saved-orders');saved.replaceChildren();for(const o of state?.orders||[]){const b=el('button',`${statusLabels[o.status]} ${o.data.customer_name||''} — ${o.id.slice(0,8)}`,'saved-order');b.onclick=()=>run(async()=>{await select(o.id);$('history-dialog').close();});saved.append(b);}const box=$('history');box.replaceChildren();for(const r of state?.history||[]){const row=el('div',undefined,'history-row');row.append(el('bdi',new Date(r.event.occurred_at).toLocaleString('ar-EG')),el('span',labels[r.event.kind]+' · '+r.order_id.slice(0,8)),el('bdi',D.money(r.event.data.total_cents)+' ج'),el('span',r.acked?'تمت المزامنة':r.last_error?'تحتاج مراجعة':'منتظرة',r.last_error?'error':''));if(['kitchen','bill','sale'].includes(r.event.kind)){const b=el('button',r.printed?'إعادة طباعة':'طباعة');b.onclick=()=>run(()=>POS.print(r.id));row.append(b);}if(r.last_error){row.title=r.last_error;}box.append(row);}}

