+    .dp-totals-compact dt { font-size: 8px; }.dp-totals-compact dd { font-size: 10px; }
+}
+
 #dining-pos [data-dining-request-bill]{background:#f58220;color:#fff;border:1px solid #de6d0c;font-weight:800;min-height:44px} #dining-pos [data-dining-request-bill]:disabled{opacity:.5}

